-- VERIFICACIÓN POSTERIOR de NEX-066. SOLO LECTURA. Cada fila debe dar ok = true. La ejecuta el responsable en la VM INMEDIATAMENTE después de aplicar la migración:
--   docker exec -i nexit-db psql -U nexit_app -d nexit -v ON_ERROR_STOP=1 < verificar-NEX-066.sql
BEGIN READ ONLY;
SELECT 'tabla movimientos_intenciones existe y está vacía al aplicar' AS control, to_regclass('public.movimientos_intenciones') IS NOT NULL AND (SELECT count(*) FROM public.movimientos_intenciones) = 0 AS ok
UNION ALL SELECT 'columna reconocida_at (ACK) y su CHECK', EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'movimientos_intenciones' AND column_name = 'reconocida_at') AND EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'movimientos_intenciones_reconocida_chk')
UNION ALL SELECT 'unicidad (empresa, clave)', EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'movimientos_intenciones_clave_uk' AND contype = 'u')
UNION ALL SELECT 'índice único parcial: una sola intención RESERVADA por empresa + usuario', EXISTS (SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'movimientos_intenciones_pendiente_uk' AND indexdef LIKE '%UNIQUE%' AND indexdef LIKE '%(empresa_id, usuario_id)%' AND indexdef LIKE '%reconocida_at IS NULL%' AND indexdef LIKE '%RESERVADA%' AND indexdef LIKE '%CONFIRMADA%')
UNION ALL SELECT 'visibilidad: la función interna existe, SECURITY DEFINER, y NI PUBLIC NI la aplicación pueden ejecutarla', to_regprocedure('public.movimiento_intencion_visible(uuid,uuid,jsonb)') IS NOT NULL AND (SELECT prosecdef FROM pg_proc WHERE oid = 'public.movimiento_intencion_visible(uuid,uuid,jsonb)'::regprocedure) AND NOT has_function_privilege('nexit_runtime', 'public.movimiento_intencion_visible(uuid,uuid,jsonb)', 'EXECUTE')
UNION ALL SELECT 'FK (empresa, usuario) → usuarios', EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'movimientos_intenciones_usuario_fk' AND contype = 'f')
UNION ALL SELECT 'las seis funciones existen y son SECURITY DEFINER con search_path fijo', (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('movimiento_intencion_reservar', 'movimiento_intencion_pendiente', 'movimiento_intencion_tomar', 'movimiento_intencion_confirmar', 'movimiento_intencion_rechazar', 'movimiento_intencion_reconocer') AND p.prosecdef AND p.proconfig IS NOT NULL AND array_to_string(p.proconfig, ',') LIKE '%search_path=public, pg_temp%') = 6
UNION ALL SELECT 'el rol de la aplicación NO tiene acceso a la tabla', NOT (has_table_privilege('nexit_runtime', 'public.movimientos_intenciones', 'SELECT') OR has_table_privilege('nexit_runtime', 'public.movimientos_intenciones', 'INSERT') OR has_table_privilege('nexit_runtime', 'public.movimientos_intenciones', 'UPDATE') OR has_table_privilege('nexit_runtime', 'public.movimientos_intenciones', 'DELETE'))
UNION ALL SELECT 'el rol de la aplicación EJECUTA las seis funciones', has_function_privilege('nexit_runtime', 'public.movimiento_intencion_reservar(uuid,uuid,text,jsonb)', 'EXECUTE') AND has_function_privilege('nexit_runtime', 'public.movimiento_intencion_pendiente(uuid,uuid)', 'EXECUTE') AND has_function_privilege('nexit_runtime', 'public.movimiento_intencion_tomar(uuid,uuid,text)', 'EXECUTE') AND has_function_privilege('nexit_runtime', 'public.movimiento_intencion_confirmar(uuid,uuid,text,uuid,text)', 'EXECUTE') AND has_function_privilege('nexit_runtime', 'public.movimiento_intencion_rechazar(uuid,uuid,text,text)', 'EXECUTE') AND has_function_privilege('nexit_runtime', 'public.movimiento_intencion_reconocer(uuid,uuid,text)', 'EXECUTE')
UNION ALL SELECT 'PUBLIC no ejecuta ninguna función de intenciones', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE n.nspname = 'public' AND p.proname LIKE 'movimiento_intencion_%' AND a.grantee = 0)
UNION ALL SELECT 'NEX-014 intacta: el motor sigue existiendo con su firma', to_regprocedure('public.inventario_registrar_movimiento(uuid,uuid,text,text,date,uuid,uuid,jsonb,text,uuid,text,text,text)') IS NOT NULL;
ROLLBACK;
